--     'unique effects'), plus requiredspell and startquest
--   * ItemLimitCategory above 85, the highest WotLK ships
--
-- 2625 items.
--
-- Most identify themselves by an '@Worldforged@' description tag. A few carry
-- no tag but sit at a recorded Worldforged find, and the gear among those is
-- taken too, so no location is left holding nothing.

DELETE FROM `item_template` WHERE `entry` IN (SELECT `item` FROM `mod_madosa_worldforged_ascension_items`);
DELETE FROM `mod_madosa_worldforged_ascension_items`;

